import{_ as r,a0 as s,w as a,s as d,ao as p,I as e,x as t,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"移动版 GNOME Shell：希望之始，期望满满 | LCTT x X-CMD","titleTemplate":false,"description":"移动版 GNOME Shell：希望之始，期望满满 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"移动版 GNOME Shell：希望之始，期望满满 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"移动版 GNOME Shell：希望之始，期望满满 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion]","title":"移动版 GNOME Shell：希望之始，期望满满","tag":"202206","desc":""},"relativePath":"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion].md","filePath":"[post].md"}'),m={name:"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion].md"};function u(h,l,M,w,g,E){const o=s("Link");return a(),d("div",null,[l[25]||(l[25]=p('<h1 id="移动版-gnome-shell-希望之始-期望满满" tabindex="-1">移动版 GNOME Shell：希望之始，期望满满 <a class="header-anchor" href="#移动版-gnome-shell-希望之始-期望满满" aria-label="Permalink to “移动版 GNOME Shell：希望之始，期望满满”">​</a></h1><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/GNOME-Shell-Running-on-a-prototype-Pinephone.jpg" alt="GNOME Shell 在一台 Pinephone 原型机上运行"></p><blockquote><p>GNOME 开发人员在最近的一篇博文中提出了将 GNOME Shell 完全移植到手机上的想法。下面是我对这个项目的一些看法。</p></blockquote><h3 id="移动版-gnome-shell" tabindex="-1">移动版 GNOME Shell <a class="header-anchor" href="#移动版-gnome-shell" aria-label="Permalink to “移动版 GNOME Shell”">​</a></h3>',4)),e("p",null,[l[1]||(l[1]=t("作为一个桌面环境，GNOME 在过去的十年中发展成为了 ",-1)),n(o,{href:"https://www.debugpoint.com/tag/gnome-40"},{default:i(()=>[...l[0]||(l[0]=[t("GNOME 40",-1)])]),_:1}),l[2]||(l[2]=t("。GNOME 40 是一个重要的版本，它以一种现代的方式改变了完整的用户界面设计。",-1))]),l[26]||(l[26]=e("p",null,"看着 GNOME 40 的设计方式，你可能会觉得 Shell 和它的底层技术已经为小屏幕做好了准备。手势驱动的工作区、图标网格和停靠区 —— 在某种程度上感觉更接近于像安卓这样的移动操作系统，而不是桌面环境。",-1)),l[27]||(l[27]=e("p",null,"此外，系统托盘、日历、通知和原生的应用程序，可以有效地在较小尺寸的设备上工作。得益于 GTK4 和 libadwaita，其设计是响应式的，应用程序和控件的外观与移动平台很匹配。",-1)),l[28]||(l[28]=e("p",null,"在 GNOME 40 之后，GNOME 开发者为较小尺寸的设备（如平板电脑和手机）设计了几个 GNOME Shell 的概念验证。",-1)),l[29]||(l[29]=e("h4",{id:"为什么是现在",tabindex:"-1"},[t("为什么是现在？ "),e("a",{class:"header-anchor",href:"#为什么是现在","aria-label":"Permalink to “为什么是现在？”"},"​")],-1)),e("p",null,[l[4]||(l[4]=t("任何项目的开发和研究工作都要花费时间和金钱。虽然有来自主要科技公司对 GNOME 的捐赠，但这次有一个 “",-1)),l[5]||(l[5]=e("ruby",null,[t("原型基金"),e("rt",null,"Prototype Fund")],-1)),l[6]||(l[6]=t("” 帮助该团队继续进行这项努力。",-1)),n(o,{href:"http://www.prototypefund.de"},{default:i(()=>[...l[3]||(l[3]=[t("原型基金",-1)])]),_:1}),l[7]||(l[7]=t(" 是德国教育部（BMBF）支持公共利益软件的资助项目。",-1))]),l[30]||(l[30]=p('<h4 id="包括什么" tabindex="-1">包括什么？ <a class="header-anchor" href="#包括什么" aria-label="Permalink to “包括什么？”">​</a></h4><p>设计一个完整的移动用户界面，并将其与移动操作系统整合是一个非常复杂的项目。它需要一个精心设计的愿景来支持成千上万的移动硬件和用户支持。更不用说，用户在移动设备上的隐私和安全问题了。</p><p>因此，有了这个基金，团队可以集中精力进行概念验证，以满足 GNOME Shell 中一些基本的用户互动。</p><ul><li>启动器</li><li>应用程序网格</li><li>轻扫、手势和导航</li><li>用手机键盘搜索</li><li>检测屏幕大小和支持屏幕旋转</li><li>工作空间和多任务</li><li>设置</li><li>屏幕键盘</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/GNOME-Shell-Mobile-mock-up.jpg" alt="GNOME Shell 移动版模拟图"></p><p>始终要记住的是，移动体验远不止用户界面这么简单。另外，GNOME 本身并不是一个操作系统。它由底层的稳定的操作系统组成，它提供了非常需要的隐私和安全。另外，“应用商店”的概念也是如此。手机制造商需要与 GNOME 开发者合作，让他们的产品采用这个概念。</p><h4 id="进展如何" tabindex="-1">进展如何？ <a class="header-anchor" href="#进展如何" aria-label="Permalink to “进展如何？”">​</a></h4><p>在写这篇文章时，团队给我们快速演示了取得的进展。在下面的视频中可以看到：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/phone.webm" alt=""></p><p>复杂的任务是识别触摸屏手机中的各种手势。例如，你可能会使用长触摸、短触摸、双指轻扫和拖动，以及许多只有在小尺寸设备中才可行的可能性。这需要在各自的 GNOME Shell 组件中推倒重构。</p><p>而完全在现有的 GNOME Shell 基础上开发它们是很有挑战性的工作。</p><p>此外，该团队使用著名的 Pinephone Pro 进行开发和测试。Pinephone 已经是一个商业产品，装有 “友商” KDE Plasma 手机和其他 Linux 操作系统。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/tablet.webm" alt=""></p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>如果一切按计划进行，我们可能在一个完整的开源手机中获得原生的 GNOME 体验。而你可以重新拥有你的隐私!</p><p>另外，我不确定 Phosh（它也是基于 GNOME 的）会发生什么。虽然 Phosh 是由 Purism 开发和管理的，但看看 GNOME Shell 在移动设备上的努力和 PHosh 在未来一段日子的发展方向将是很有趣的。</p><p>那么，你对这个项目的前景怎么看？请在下面的评论栏里告诉我。</p>',17)),e("p",null,[e("em",null,[l[9]||(l[9]=t("图片和视频来源：GNOME 开发者 ",-1)),n(o,{href:"https://blogs.gnome.org/shell-dev/2022/05/30/towards-gnome-shell-on-mobile/"},{default:i(()=>[...l[8]||(l[8]=[t("博客",-1)])]),_:1})])]),l[31]||(l[31]=e("hr",null,null,-1)),e("p",null,[l[11]||(l[11]=t("via: ",-1)),n(o,{href:"https://www.debugpoint.com/2022/06/gnome-shell-mobile-announcement/"},{default:i(()=>[...l[10]||(l[10]=[t("https://www.debugpoint.com/2022/06/gnome-shell-mobile-announcement/",-1)])]),_:1})]),e("p",null,[l[16]||(l[16]=t("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...l[12]||(l[12]=[t("Arindam",-1)])]),_:1}),l[17]||(l[17]=t(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:i(()=>[...l[13]||(l[13]=[t("lkxed",-1)])]),_:1}),l[18]||(l[18]=t(" 译者：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...l[14]||(l[14]=[t("wxy",-1)])]),_:1}),l[19]||(l[19]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...l[15]||(l[15]=[t("wxy",-1)])]),_:1})]),e("p",null,[l[22]||(l[22]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[20]||(l[20]=[t("LCTT",-1)])]),_:1}),l[23]||(l[23]=t(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...l[21]||(l[21]=[t("Linux中国",-1)])]),_:1}),l[24]||(l[24]=t(" 荣誉推出",-1))])])}const f=r(m,[["render",u]]);export{b as __pageData,f as default};
